item.command:
/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { validate } from 'axylo';
import render from './chart.js';

assert.equal(typeof render, 'function');
assert.equal(render.name, 'render');
assert.equal(render.length, 2);

const data = JSON.parse(readFileSync('data.json', 'utf8'));
const problems = validate('line', {
  title: 'Daily visits',
  data,
  x: { field: 'day', type: 'date' },
  y: { field: 'visits', label: 'Visits' },
});

for (const { code, level, message } of problems) {
  console.log(code, level, message);
}
assert.deepEqual(problems.filter(({ level }) => level "'!== '"'hint'), []);
console.log("'`Validated ${data.length} rows with no errors or warnings.`);
NODE'
